def solve(input_data):
    weighted_graph = input_data["weighted_graph"]
    start = input_data["start"]
    dist = {node: float('inf') for node in weighted_graph}
    dist[start] = 0
    import heapq
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in weighted_graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    answer = {}
    for node in weighted_graph:
        val = dist[node]
        answer[node] = val if val != float('inf') else None
    return answer

