def trace(input_data):
    sess = TraceSession(
        algorithm="Bellman-Ford Algorithm",
        input_data=input_data,
        pseudocode=[
            "Initialize distances: source 0, others infinity",
            "Build list of all edges (u, v, w)",
            "Repeat |V|-1 times: relax every edge",
            "If no distance is updated in a pass, stop early",
            "Return distances"
        ]
    )
    weighted_graph = input_data["weighted_graph"]
    start = input_data["start"]
    nodes = list(weighted_graph.keys())
    edges = [(u, v, w) for u in nodes for v, w in weighted_graph[u]]
    g = sess.graph("graph", nodes, edges, directed=True)

    dist_map = sess.map("dist", {node: float('inf') for node in nodes})
    dist_map[start] = 0

    dist = {node: float('inf') for node in nodes}
    dist[start] = 0

    for i in range(len(nodes) - 1):
        with sess.step(f"Pass {i+1}"):
            updated = False
            for u, v, w in edges:
                g.highlight_edge(u, v)
                if dist[u] + w < dist[v]:
                    sess.note(f"Relax edge ({u},{v}): {dist[u]}+{w} < {dist[v]}")
                    dist[v] = dist[u] + w
                    dist_map[v] = dist[v]
                    updated = True
                    g.highlight_node(v)
            if not updated:
                sess.note("No improvement, early termination")
                break

    answer = {node: (val if val != float('inf') else None) for node, val in dist.items()}
    sess.result(answer)

    trace = sess.to_trace()
    for event in trace["events"]:
        op = event.get("op")
        targets = [t.get("id", "") for t in event.get("targets", [])]
        reason = event.get("reason", "")
        if op == "create":
            if "graph" in targets:
                event["code_line"] = 3
            elif "dist" in targets:
                event["code_line"] = 7
        elif op == "set" and "dist" in targets:
            if "source" in reason:
                event["code_line"] = 8
            else:
                event["code_line"] = 13
        elif op == "highlight" and "edge" in reason:
            event["code_line"] = 12
        elif op == "note":
            if "Relax" in reason:
                event["code_line"] = 13
            elif "No improvement" in reason:
                event["code_line"] = 16
        elif op in ("enter", "exit"):
            event["code_line"] = 10
        elif event.get("role") == "answer" or "answer" in targets:
            event["code_line"] = 19
    return trace
